/// Returns true iff a and b are anagrams (same multiset of characters).
pub fn is_anagram(a: &str, b: &str) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    a_chars.sort();
    b_chars.sort();
    a_chars == b_chars
}

