use std::vec::Vec;

/// Merges two already-sorted ascending vectors into a single sorted vector.
/// Duplicates from both inputs are kept (so [1,2] + [2,3] -> [1,2,2,3]).
pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let m = merge_sorted(&[1, 4, 7], &[2, 3, 8]);
    println!("{:?}", m);
}

#[test]
fn test_merge_sorted() {
    assert_eq!(merge_sorted(&[], &[]), Vec::new());
    assert_eq!(merge_sorted(&[], &[1, 2]), vec![1, 2]);
    assert_eq!(merge_sorted(&[1, 2], &[3, 4]), vec![1, 2, 3, 4]);
    assert_eq!(merge_sorted(&[1, 2, 3], &[4, 5]), vec![1, 2, 3, 4, 5]);
    assert_eq!(merge_sorted(&[1, 2, 2], &[2, 3]), vec![1, 2, 2, 2, 3]);
}

use std::collections::HashMap;

/// Parses a string like "foo=bar, baz= qux " into a HashMap.
/// Whitespace around keys and values is trimmed.
/// Returns Err if any pair is missing `=`.
pub fn parse_kv(s: &str) -> Result<HashMap<String, String>, String> {
    let mut out = HashMap::new();
    if s.trim().is_empty() {
        return Ok(out);
    }
    for pair in s.split(',') {
        let pair = pair.trim();
        let (k, v) = pair.split_once('=').ok_or_else(|| format!("missing '=' in pair: {}", pair))?;
        out.insert(k.trim().to_string(), v.trim().to_string());
    }
    Ok(out)
}

fn main() {
    println!("{:?}", parse_kv("a=1, b=2"));
}

#[test]
fn test_normal() {
    let input = "a=1, b=2";
    let result = parse_kv(input);
    assert_eq!(result, HashMap::from([("a", "1"), ("b", "2")]));
}

#[test]
fn test_multiple_pairs() {
    let input = "foo=bar, baz=qux";
    let result = parse_kv(input);
    assert_eq!(result, HashMap::from([("foo", "bar"), ("baz", "qux")]));
}

#[test]
fn test_whitespace() {
    let input = " foo=bar,  baz= qux ";
    let result = parse_kv(input);
    assert_eq!(result, HashMap::from([("foo", "bar"), ("baz", "qux")]));
}

#[test]
fn test_empty_input() {
    let input = "";
