}

/// Safely divides two integers; returns Err on division by zero.
pub fn safe_divide(a: i32, b: i32) -> Result<i32, String> {
    if b == 0 {
        Err("division by zero".to_string())
    } else {
        Ok(a / b)
    }
}

fn main() {
    println!("{:?}", safe_divide(10, 2));
}

#[test]
fn test_safe_divide() {
    // Normal division
    assert_eq!(safe_divide(10, 2), Ok(5));
    // Division by zero
    assert_eq!(safe_divide(10, 0), Err("division by zero".to_string()));
    // Negative dividend
    assert_eq!(safe_divide(-10, 2), Ok(-5));
    // Zero dividend (a is 0, b is non-zero)
    assert_eq!(safe_divide(0, 3), Ok(0));
}

pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self { Stack { items: Vec::new() } }
    pub fn push(&mut self, x: T) { self.items.push(x); }
    pub fn pop(&mut self) -> Option<T> { self.items.pop() }
    pub fn peek(&self) -> Option<&T> { self.items.last() }
    pub fn len(&self) -> usize { self.items.len() }
    pub fn is_empty(&self) -> bool { self.items.is_empty() }
}

fn main() {
    let mut s: Stack<i32> = Stack::new();
    s.push(1);
    s.push(2);
    println!("top: {:?}, len: {}", s.peek(), s.len());
}

#[test]
fn test_stack() {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None);
    assert_eq!(s.len(), 0);
    assert_eq!(s.is_empty(), true);

    // Test peek on non-empty
    let mut s = Stack::new();
    s.push(1);
    assert_eq!(s.peek(), Some(&1));
    s.pop();
    assert_eq!(s.peek(), Some(&1));
    s.push(2);
    assert_eq!(s.peek(), Some(&2));
    s.pop();
    assert_eq!(s.peek(), Some(&1));
    s.pop();
    assert_eq!(s.peek(), None);
}

