use std::collections::HashMap;

fn unique_only(items: Vec<String>) -> Vec<String> {
    let mut counts: HashMap<&String, i32> = HashMap::new();
    for item in items {
        *counts.entry(&item).or_insert(0) += 1;
    }
    counts
        .iter()
        .filter(|(_, c)| **c == 1)
        .map(|(k, _)| k.to_string())
        .collect()
}

